 $card=$f->request('GET','/pilot/objects/4512',[],$actor);@$dom->loadHTML('<?xml encoding="UTF-8">'.$card['body']);$section=(new DOMXPath($dom))->query('//*[@id="object-comment"]')->item(0);assertSameValue(true,str_contains($section->textContent,$firstEvent['actor_display_snapshot']),'latest comment attribution remains original after unrelated edit');assertSameValue(false,str_contains($section->textContent,'Техническое изменение'),'technical editor not attributed as comment author');
 $f->db->query("INSERT IGNORE INTO {$p}fm2_pilot_role_permissions(role_id,permission)VALUES(7,'objects.details.edit')");$manager=[];$f->login($manager,97);assertSameValue(303,$post('Комментарий руководителя',2,3,$manager)['status'],'manager can edit');
 $before=$f->facts();$conflict=$post('Мой несохранённый комментарий',2,4,$actor);assertSameValue(409,$conflict['status'],'stale comment rejected');assertSameValue($before,$f->facts(),'conflict no writes');assertSameValue(true,str_contains($conflict['body'],'Мой несохранённый комментарий')&&str_contains($conflict['body'],'Комментарий руководителя'),'conflict retains submitted and persisted text');assertSameValue(false,str_contains($conflict['body'],'data-object-details-invalid'),'comment conflict does not open technical editor');
 $before=$f->facts();$invalid=$post(str_repeat('Ж',2001),3,5,$actor);assertSameValue(422,$invalid['status'],'Unicode length server enforced');assertSameValue($before,$f->facts(),'invalid no writes');assertSameValue(true,str_contains($invalid['body'],str_repeat('Ж',2001)),'invalid typed value retained');
 $registry=new ObjectDetailsFieldRegistry();assertSameValue(['comment'=>str_repeat('Ж',2000)],$registry->normalizePatch(['comment'=>str_repeat('Ж',2000)]),'2000 Unicode characters accepted');foreach(["bad\0text","bad\x01text","bad\xC2\x85text","\xFF"]as$invalidText){$rejected=false;try{$registry->normalizePatch(['comment'=>$invalidText]);}catch(InvalidArgumentException){$rejected=true;}assertSameValue(true,$rejected,'unsafe text rejected');}
 $reader=[];$f->login($reader,95);$read=$f->request('GET','/pilot/objects/4512',[],$reader);assertSameValue(200,$read['status'],'reader sees card');assertSameValue(true,str_contains($read['body'],'Комментарий руководителя'),'reader sees comment');assertSameValue(false,str_contains($read['body'],'data-object-comment-form'),'reader cannot edit');$f->db->query("INSERT IGNORE INTO {$p}fm2_pilot_role_permissions(role_id,permission)VALUES(5,'objects.details.edit')");$wrongRole=$f->request('GET','/pilot/objects/4512',[],$reader);assertSameValue(false,str_contains($wrongRole['body'],'data-object-comment-form'),'wrong role remains read-only even with details capability');$before=$f->facts();assertSameValue(403,$post('Запрещено',3,6,$reader)['status'],'server denies read-only actor');assertSameValue($before,$f->facts(),'denied no writes');
 $before=$f->facts();assertSameValue(400,$f->form('/pilot/objects/4512/details',['requestId'=>'eeeeeeee-0000-4000-8000-000000000007','expectedRevision'=>'3','comment'=>'CSRF'],$actor)['status'],'CSRF required');assertSameValue($before,$f->facts(),'CSRF denial no writes');
 assertSameValue(303,$post(" \n ",3,8,$actor)['status'],'explicit clear accepted');assertSameValue(null,$comment(),'blank clears current comment');assertSameValue($firstEvent['changes_json'],$f->db->query("SELECT changes_json FROM {$p}fm2_object_detail_edit_events WHERE revision=1")->fetch_column(),'old comment history immutable after edits and clear');assertSameValue(4,$revision(),'only accepted changes increment revision');
 echo "PASS: object comments HTTP/plain text/history/permissions/replay/conflict\n";
